-- (re)surgentes back office. Run once in Supabase: SQL Editor > New query > paste > Run.
-- Then load the current content with supabase/seed.sql (generated by `npm run seed:sql`).

-- Who can use the back office. Being logged in is not enough: the email must be listed here.
create table if not exists public.editors (
  email text primary key check (email = lower(email)),
  created_at timestamptz not null default now()
);

create or replace function public.is_editor() returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.editors where email = lower(auth.jwt() ->> 'email'))
$$;

-- Agenda. Same shape as src/content/agenda.json ("end" is a reserved word, so end_date).
create table if not exists public.events (
  id text primary key,
  date date not null,
  end_date date check (end_date is null or end_date >= date),
  precision text not null default 'day' check (precision in ('day', 'month')),
  kind text not null check (kind in ('activity', 'news')),
  assembly text not null check (assembly in ('br', 'ar', 'co', 'mx', 'red')),
  place text,
  url text,
  title jsonb not null check (title ? 'es'),
  text jsonb,
  published boolean not null default true,
  updated_at timestamptz not null default now()
);

-- Library. Same shape as src/content/recursos.json, plus manual order.
create table if not exists public.resources (
  id uuid primary key default gen_random_uuid(),
  assembly text not null check (assembly in ('br', 'ar', 'co', 'mx', 'red')),
  type text not null check (type in ('report', 'press', 'video', 'social', 'gallery')),
  lang text not null check (lang in ('es', 'pt', 'en')),
  source text not null,
  title jsonb not null check (title ? 'es'),
  url text not null,
  youtube text,
  position integer not null default 0,
  published boolean not null default true,
  updated_at timestamptz not null default now()
);

-- Contact form. Field names match src/components/ContactForm.jsx.
create table if not exists public.messages (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  name text not null check (length(name) between 1 and 200),
  email text not null check (length(email) between 3 and 320),
  country text check (length(country) <= 100),
  reason text check (length(reason) <= 200),
  message text not null check (length(message) between 1 and 5000),
  lang text check (lang in ('es', 'pt')),
  status text not null default 'new' check (status in ('new', 'read', 'archived'))
);

create or replace function public.touch() returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end $$;
drop trigger if exists events_touch on public.events;
create trigger events_touch before update on public.events for each row execute function public.touch();
drop trigger if exists resources_touch on public.resources;
create trigger resources_touch before update on public.resources for each row execute function public.touch();

-- Access rules. The anon key ships in the public site, so these are the real security boundary.
alter table public.editors enable row level security;
alter table public.events enable row level security;
alter table public.resources enable row level security;
alter table public.messages enable row level security;

drop policy if exists "editors see the team" on public.editors;
create policy "editors see the team" on public.editors for select to authenticated using (public.is_editor());

drop policy if exists "public reads published events" on public.events;
create policy "public reads published events" on public.events for select to anon, authenticated using (published or public.is_editor());
drop policy if exists "editors manage events" on public.events;
create policy "editors manage events" on public.events for all to authenticated using (public.is_editor()) with check (public.is_editor());

drop policy if exists "public reads published resources" on public.resources;
create policy "public reads published resources" on public.resources for select to anon, authenticated using (published or public.is_editor());
drop policy if exists "editors manage resources" on public.resources;
create policy "editors manage resources" on public.resources for all to authenticated using (public.is_editor()) with check (public.is_editor());

-- Anyone can send a message, but only as "new"; nobody outside the team can read them.
drop policy if exists "anyone sends a message" on public.messages;
create policy "anyone sends a message" on public.messages for insert to anon, authenticated with check (status = 'new');
drop policy if exists "editors read messages" on public.messages;
create policy "editors read messages" on public.messages for select to authenticated using (public.is_editor());
drop policy if exists "editors update messages" on public.messages;
create policy "editors update messages" on public.messages for update to authenticated using (public.is_editor()) with check (public.is_editor());
drop policy if exists "editors delete messages" on public.messages;
create policy "editors delete messages" on public.messages for delete to authenticated using (public.is_editor());

-- Column grants: the public form can only fill these fields (not id, created_at or status).
revoke insert on public.messages from anon;
grant insert (name, email, country, reason, message, lang) on public.messages to anon;

-- Add the team (lowercase emails), and invite the same emails in Authentication > Users:
-- insert into public.editors (email) values ('persona@ejemplo.org');
